INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Kanalizasyon Taştı','Sağanak yağmurdan sonra eski kanalizasyon hattı patladı. Çarşı mahallesinde sokaklar iki gündür lağım kokuyor.',NULL,'{"health": "Mide-bağırsak enfeksiyonu vakaları arttı.", "social": "Esnaf dükkânlarını kapattı."}'::jsonb,-25000,'{"health": -5, "social": -2}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Kanalizasyon Taştı');
INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Okulda Yangın','Cumhuriyet İlkokulu''nun kazan dairesinde çıkan yangında kimse yaralanmadı ama binanın yarısı kullanılamaz durumda.',NULL,'{"education": "Öğrenciler ikili öğretime geçti.", "security": "Yangın denetimleri sorgulanıyor."}'::jsonb,-30000,'{"education": -6, "security": -1}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Okulda Yangın');
INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Toplu İşten Çıkarma','İlçenin en büyük lojistik firması 250 çalışanını tek bir e-postayla işten çıkardı.',NULL,'{"social": "Mahallelerde öfke büyüyor.", "economy": "Vergi geliri düştü, harcamalar azaldı."}'::jsonb,-15000,'{"social": -6, "businessman_cash": -40000}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Toplu İşten Çıkarma');
INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Doktor İstifaları','Devlet hastanesinden üç uzman doktor aynı hafta içinde özel sektöre geçti.',NULL,'{"health": "Poliklinik randevuları üç haftaya uzadı."}'::jsonb,0,'{"health": -6}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Doktor İstifaları');
INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Çete Kavgası','Gece yarısı sahil yolunda iki grup arasında çıkan silahlı kavga sosyal medyada yayıldı.',NULL,'{"security": "Akşamları sokaklar boşaldı.", "social": "Aileler çocuklarını dışarı çıkarmıyor."}'::jsonb,0,'{"security": -6, "social": -2}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Çete Kavgası');
INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'event','Zincirleme Trafik Kazası','Çevre yolunda sis yüzünden 14 araç birbirine girdi; ana arter saatlerce kapalı kaldı.',NULL,'{"transport": "Servis ve otobüs seferleri aksadı.", "health": "Acil servis bir gece boyunca doldu."}'::jsonb,-10000,'{"transport": -6, "health": -1}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Zincirleme Trafik Kazası');
